#!/usr/bin/env bash
# Build the whole app into ONE runnable jar. The Maven build runs the front-end (frontend-maven-
# plugin) into src/main/resources/static, then packages the Spring Boot app (spring-boot repackage,
# main net.officefloor.hq.app.Application) into target/*.jar. PINNED — do not edit.
# Contract: BASE_CHECKLIST.md §B, §C. Must succeed from a clean base-empty checkout (§A).
set -euo pipefail
cd "$(dirname "$0")/.."

# One command: the pom's frontend-maven-plugin builds the SPA into src/main/resources/static.
# `clean` first so removed sources (e.g. a deleted route .yml or class) can't linger in
# target/classes and get baked into the jar (found via the cp01 dry run).
exec ./mvnw -q -DskipTests clean package
# TODO: add the Maven wrapper (./mvnw) or switch to `mvn` if a system Maven is guaranteed.
===ROUTER===
src/main/frontend/router:
routes.ts

src/main/frontend/ui:
===routes===
// Manifest-based routing (shared surface). A feature is a NEW file at features/<name>/feature.tsx
// that exports a `feature: Feature`; it is discovered here via import.meta.glob, so adding a page is
// a new file — never an edit to this router (DESIGN.md §8).
import type { ComponentType } from 'react';

export type Feature = {
  id: string; // section id -> nav-<id> data-testid
  label: string; // nav link text
  Page: ComponentType;
};

const modules = import.meta.glob<{ feature: Feature }>('../features/*/feature.tsx', { eager: true });

export const features: Feature[] = Object.values(modules)
  .map((m) => m.feature)
  .filter((f): f is Feature => Boolean(f))
  .sort((a, b) => a.label.localeCompare(b.label));

